        if (!VoxRlMultiplyU32(static_cast<u32>(campaignOperationArmyIds.size()), sizeof(CampaignOperationArmyIdRecord), length) || !VoxRlAlignU32(offset, offset) || !VoxRlAddU32(offset, length, offset)) return false;
