// Appends rows to replayAssignments and assigns ReplayHeaderRecord.assignmentRange.
inline bool AppendReplayHeaderRecordAssignmentRange(ReplayHeaderRecord* parent, VoxRlReplayPlanData* data, const std::vector<ReplayAssignmentRecord>& rows)
{
    if (parent == 0 || data == 0 || !VoxRlBuilderSizeFitsU32(data->replayAssignments.size()) || !VoxRlBuilderSizeFitsU32(rows.size())) return false;
    const u32 first = static_cast<u32>(data->replayAssignments.size());
    const u32 count = static_cast<u32>(rows.size());
    u32 end = 0; if (!VoxRlAddU32(first, count, end)) return false;
    data->replayAssignments.insert(data->replayAssignments.end(), rows.begin(), rows.end());
    parent->assignmentRangeFirst = first; parent->assignmentRangeCount = count; return true;
}

